    "IT.REDSHARD.name": "Red Shard",  // Red Shard
    "IT.REDSHARD.plural": "Red Shards",  // Red Shards
    "IT.REDSHARD.desc": "A small red shard. It appears to be from some sort of implement made long ago.",  // A small red shard. It appears to be from some sort of implement made long ago.
    "IT.YELLOWSHARD.name": "Yellow Shard",  // Yellow Shard
    "IT.YELLOWSHARD.plural": "Yellow Shards",  // Yellow Shards
    "IT.YELLOWSHARD.desc": "A small yellow shard. It appears to be from some sort of implement made long ago.",  // A small yellow shard. It appears to be from some sort of implement made long ago.
    "IT.BLUESHARD.name": "Blue Shard",  // Blue Shard
    "IT.BLUESHARD.plural": "Blue Shards",  // Blue Shards
    "IT.BLUESHARD.desc": "A small blue shard. It appears to be from some sort of implement made long ago.",  // A small blue shard. It appears to be from some sort of implement made long ago.
    "IT.GREENSHARD.name": "Green Shard",  // Green Shard
    "IT.GREENSHARD.plural": "Green Shards",  // Green Shards
    "IT.GREENSHARD.desc": "A small green shard. It appears to be from some sort of implement made long ago.",  // A small green shard. It appears to be from some sort of implement made long ago.
    "IT.FIRESTONE.name": "Fire Stone",  // Fire Stone
    "IT.FIRESTONE.plural": "Fire Stones",  // Fire Stones
    "IT.FIRESTONE.desc": "A peculiar stone that makes certain species of Pokémon evolve. It is colored orange.",  // A peculiar stone that makes certain species of Pokémon evolve. It is colored orange.
    "IT.THUNDERSTONE.name": "Thunder Stone",  // Thunder Stone
    "IT.THUNDERSTONE.plural": "Thunder Stones",  // Thunder Stones
    "IT.THUNDERSTONE.desc": "A peculiar stone that makes certain species of Pokémon evolve. It has a thunderbolt pattern.",  // A peculiar stone that makes certain species of Pokémon evolve. It has a thunderbolt pattern.
    "IT.WATERSTONE.name": "Water Stone",  // Water Stone
    "IT.WATERSTONE.plural": "Water Stones",  // Water Stones
    "IT.WATERSTONE.desc": "A peculiar stone that makes certain species of Pokémon evolve. It is a clear, light blue.",  // A peculiar stone that makes certain species of Pokémon evolve. It is a clear, light blue.
    "IT.LEAFSTONE.name": "Leaf Stone",  // Leaf Stone
    "IT.LEAFSTONE.plural": "Leaf Stones",  // Leaf Stones
    "IT.LEAFSTONE.desc": "A peculiar stone that makes certain species of Pokémon evolve. It has a leaf pattern.",  // A peculiar stone that makes certain species of Pokémon evolve. It has a leaf pattern.
    "IT.MOONSTONE.name": "Moon Stone",  // Moon Stone
    "IT.MOONSTONE.plural": "Moon Stones",  // Moon Stones
    "IT.MOONSTONE.desc": "A peculiar stone that makes certain species of Pokémon evolve. It is as black as the night sky.",  // A peculiar stone that makes certain species of Pokémon evolve. It is as black as the night sky.
    "IT.SUNSTONE.name": "Sun Stone",  // Sun Stone
    "IT.SUNSTONE.plural": "Sun Stones",  // Sun Stones
